from rules import departures, visit_mask


def solve(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = visit_mask(source, required)
    initial = (source, initial_mask, data["coupons"])
    distance = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            for next_time, next_remaining in departures(edge, arrival, remaining):
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_mask(next_node, required)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(
                        queue,
                        (next_time, next_node, next_mask, next_remaining),
                    )

    return {"arrival": None}
